declare namespace Path {
    /** Retrieves an alternate directory separator character This method retrieves one of the two currently specified directory seperator characters used by paths '/'. */
    function GetAltDirectorySeparatorChar(this: void): string;
    /** Returns a path to the deepest folder containing the target When used with paths to files, this method returns the folder containing the file.  When used with paths to directories, this method returns the folder containing the directory. */
    function GetDirectoryName(this: void, path: string): string;
    /** Gets the character used to seperate directories in a path. This method returns the character used to seperate directories in a path with ("\"). */
    function GetDirectorySeparatorChar(this: void): string;
    /** Returns the extension of a file This method returns the extension of a target file.  Returns an empty string if it cannot determine extension. */
    function GetExtension(this: void, path: string): string;
    /** Gets the character used to mark a file extension This method reutnrs the character used to begin a file extension in a path. "." */
    function GetExtensionSeparatorChar(this: void): any;
    /** Gets the file name in the target path This method returns the complete filename in a path, including the extension. */
    function GetFileName(this: void, path: string): string;
    /** Obtains the filename without the extension for a given path This method returns the name of the file, minus extension, in a given path. */
    function GetFileNameWithoutExtension(this: void, path: string): string;
    /** Grabs the character used to seperate multiple paths This returns the character used to separate multiple paths. */
    function GetPathSeparatorChar(this: void): string;
    /** Returns the character used to separate volumes in a path. This method returns the character used to separate volumes in a path. ":" */
    function GetVolumeSeparatorChar(this: void): string;
    /** Returns a path in which all directory seperators are the same This method receives a path and returns the same path but with all directory separators set to use the character returned in Path.GetDirectorySeperatorChar(). */
    function NormalizePath(this: void, path: string): string;
    function UsesExtension(this: void, file: string, arg1: string): int;
}

