declare namespace DB {
    /** Tells the engine to gather SQL memory usage This method tells the engine to gather extended memory information by walking the heap associated with SQL.  This method is used in conjunction with DB.GetMemoryUsage and will allow it to return more detailed information.  Each time this method is called, it updates the information snapshot returned by DB.GetMemoryUsage.  It is not recommended to execute this method on a per-frame basis as it can be quite slow. */
    function CollectMemoryUsage(this: void, ...args: any[]): any;
    function CreateQuery(this: void, sql: string): void;
    /** Returns the amount of memory currently in use by SQL */
    function GetMemoryUsage(this: void): LuaTable;
    /** Executes an arbitrary SQL statement on the gameplay database and returns recordset. In situations where the quick and easy enumeration that GameInfo provides is not enough and either updates to the database or a complex query such as a join is required, DB.Query can be used.  This method executes any arbitrary SQL command on the gameplay database and returns a recordset.  Variable arguments can be used in the SQL command.  For information about how to use literal arguments, see [http://www.sqlite.org/c3ref/bind_blob.html */
    function Query(this: void, sql: string, ...args: any[]): LuaIterable<{ readonly [column: string]: any }>;
    /** Returns the number of active SQL commands */
    function StatementCount(this: void): int;
    /** Returns the SQL string for the specified active SQL query index Used as a debug mechanism, returns the SQL text used for a specific active SQL query index. */
    function StatementSQL(this: void, statement_index: int): string;
}

